import { ReadableStream, WritableStream, TransformStream } from "node:stream/web";
import { out, deferred, result, caught, launch } from "./helpers.js";

export function reportPipes() { launch(async () => {
  for (const highWaterMark of [1, 4]) {
    const log = [];
    const source = new ReadableStream({ start(c) { for (const v of [1, 2, 3]) c.enqueue(v); c.close(); } });
    const sink = new WritableStream({ write(v) { log.push(v); }, close() { log.push("closed"); } }, { highWaterMark });
    const p = source.pipeTo(sink);
    out("locks", highWaterMark, source.locked, sink.locked);
    out("pipe", await p, log.join(","), source.locked, sink.locked);
  }
  {
    let controller;
    const source = new ReadableStream({ start(c) { controller = c; } }, { highWaterMark: 0 });
    const got = [], sink = new WritableStream({ write(v) { got.push(v); }, close() { got.push("close"); } });
    const p = source.pipeTo(sink);
    controller.enqueue("last"); controller.close(); await p;
    out("pending-last", got.join(","), source.locked, sink.locked);
  }
  {
    const entered = deferred(), gate = deferred(), log = [];
    const source = new ReadableStream({ start(c) { c.enqueue("last"); c.close(); } });
    const sink = new WritableStream({ async write(v) { log.push(v); entered.resolve(); await gate.promise; log.push("written"); }, close() { log.push("closed"); } });
    const p = source.pipeTo(sink); await entered.promise;
    out("final-inflight", log.join(","), source.locked, sink.locked);
    gate.resolve(); await p; out("final-settled", log.join(","), source.locked, sink.locked);
  }
  {
    const entered = deferred(), gate = deferred(); let pulls = 0;
    const source = new ReadableStream({ pull(c) { c.enqueue(++pulls); if (pulls === 3) c.close(); } }, { highWaterMark: 0 });
    const got = [], sink = new WritableStream({ async write(v) { got.push(v); if (v === 1) { entered.resolve(); await gate.promise; } } });
    const p = source.pipeTo(sink); await entered.promise;
    out("pipe-demand", pulls, got.join(",")); gate.resolve(); await p;
    out("pipe-drain", pulls, got.join(","));
  }
  for (const preventClose of [false, true]) {
    const log = [], source = ReadableStream.from(["a", "b"]);
    const sink = new WritableStream({ write(v) { log.push(v); }, close() { log.push("close"); } });
    await source.pipeTo(sink, { preventClose });
    out("prevent-close", preventClose, log.join(","), source.locked, sink.locked);
    const w = sink.getWriter(); out("after-pipe", await result(w.write("later")));
    if (preventClose) await w.close(); w.releaseLock();
  }
  {
    const source = ReadableStream.from([1, 2]);
    const twice = new TransformStream({ transform(v, c) { c.enqueue(v * 2); } });
    const plus = new TransformStream({ transform(v, c) { c.enqueue(v + 1); }, flush(c) { c.enqueue("flush"); } });
    const got = [], sink = new WritableStream({ write(v) { got.push(v); } });
    const output = source.pipeThrough(twice).pipeThrough(plus);
    out("chain-locked", source.locked, twice.writable.locked, twice.readable.locked, plus.writable.locked, output === plus.readable);
    await output.pipeTo(sink);
    out("chain", got.join(","), ...[source, twice.writable, twice.readable, plus.writable, plus.readable, sink].map(s => s.locked));
  }
  {
    const source = ReadableStream.from(["kept-open"]), t = new TransformStream();
    const output = source.pipeThrough(t, { preventClose: true }), reader = output.getReader();
    out("through-prevent-close", (await reader.read()).value);
    await new Promise(resolve => setTimeout(resolve, 0));
    out("through-released", source.locked, t.writable.locked);
    await t.writable.close(); out("through-manual-close", (await reader.read()).done); reader.releaseLock();
  }
  {
    const got = [], source = ReadableStream.from(["internal"]), sink = new WritableStream({ write(v) { got.push(v); } });
    source.getReader = sink.getWriter = () => { throw new Error("public acquisition override"); };
    await source.pipeTo(sink); out("internal-locks", got.join(","), source.locked, sink.locked);
  }
  {
    const order = [], source = new ReadableStream({ start(c) { c.close(); } }), sink = new WritableStream();
    const options = Object.fromEntries(["preventAbort", "preventCancel", "preventClose", "signal"].map(name => [name, undefined]));
    for (const name of Object.keys(options)) Object.defineProperty(options, name, { get() { order.push(name); return undefined; } });
    await source.pipeTo(sink, options); out("option-order", order.join(","));
  }
  for (const options of [null, [], () => {}]) {
    const source = new ReadableStream({ start(c) { c.close(); } });
    out("option-object", await result(source.pipeTo(new WritableStream(), options)));
  }
  out("invalid-source", await result(ReadableStream.prototype.pipeTo.call({}, new WritableStream())));
  out("invalid-destination", await result(new ReadableStream().pipeTo({})));
  out("invalid-options", await result(new ReadableStream().pipeTo(new WritableStream(), 1)));
  out("invalid-signal", await result(new ReadableStream().pipeTo(new WritableStream(), { signal: null })));
  out("invalid-through", caught(() => new ReadableStream().pipeThrough({})), caught(() => new ReadableStream().pipeThrough({ readable: new ReadableStream(), writable: {} })));
  {
    const source = new ReadableStream(), sink = new WritableStream(), r = source.getReader();
    out("locked-source", await result(source.pipeTo(sink)), caught(() => source.pipeThrough({ readable: new ReadableStream(), writable: sink })), sink.locked);
    r.releaseLock(); const w = sink.getWriter();
    out("locked-sink", await result(source.pipeTo(sink)), source.locked); w.releaseLock();
  }
  for (const closing of [false, true]) {
    const gate = deferred(), reason = deferred();
    const sink = new WritableStream({ close() { return gate.promise; } });
    const close = sink.close(); if (!closing) { gate.resolve(); await close; }
    const source = new ReadableStream({ cancel(e) { reason.resolve(e); } });
    const p = source.pipeTo(sink);
    out("closed-destination", closing, await result(p), (await reason.promise).code, source.locked, sink.locked);
    gate.resolve(); await close;
  }
}); }
